class Solution:
    def uniquePathsIII(self, grid: list[list[int]]) -> int:
        rows, cols = len(grid), len(grid[0])
        empty = 1
        sr = sc = 0
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == 0:
                    empty += 1
                elif grid[r][c] == 1:
                    sr, sc = r, c
        self.result = 0
        def dfs(r, c, remaining):
            if grid[r][c] == 2:
                if remaining == 0:
                    self.result += 1
                return
            temp = grid[r][c]
            grid[r][c] = -1
            for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != -1:
                    dfs(nr, nc, remaining - 1)
            grid[r][c] = temp
        dfs(sr, sc, empty)
        return self.result

